using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();
app.MapMcp();                      // Exposes MCP endpoint at /mcp (Streamable HTTP)
app.MapGet("/health", () => "ok"); // Health check for container orchestrators
app.Run();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"), Description("Returns current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "Service Endpoints",
        MimeType = "application/json"), Description("Lists available service endpoints")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Api = "https://api.example.com/v2",
            Auth = "https://auth.example.com",
            Storage = "https://storage.example.com"
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Validates a configuration key exists and returns its value.")]
    public static string ValidateConfigKey(
        [Description("The configuration key to look up (e.g., 'MaxRetries')")] string key)
    {
        var knownKeys = new Dictionary<string, string>
        {
            ["Environment"] = "Production",
            ["MaxRetries"] = "3",
            ["TimeoutSeconds"] = "30"
        };

        return knownKeys.TryGetValue(key, out var value)
            ? $"✓ '{key}' = {value}"
            : $"✗ '{key}' not found. Available keys: {string.Join(", ", knownKeys.Keys)}";
    }
}

